void Solver::bump_var(int var, double coeff) {
    double inc = var_inc * coeff;
    double newAct = activity[var] + inc;
    activity[var] = newAct;
    if (newAct > 1e100) {
        const double SCALE = 1e-100;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= SCALE;
        }
        var_inc *= SCALE;
    }
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
